import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  accordionHeaderClassName,
  accordionIconClassName,
  accordionItemClassName,
  accordionPanelClassName,
  accordionRootClassName,
  accordionTriggerClassName,
} from "./view";

export {
  accordionHeaderClassName,
  accordionIconClassName,
  accordionItemClassName,
  accordionPanelClassName,
  accordionRootClassName,
  accordionTriggerClassName,
} from "./view";

export type AccordionStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  openValues: readonly string[];
  className?: string | undefined;
  style?: AccordionStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  value: string;
  openValues: readonly string[];
  onValueChange: ParentMessage;
  title: string;
  children: readonly Html[];
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: AccordionStyle | undefined;
  triggerClassName?: string | undefined;
  panelClassName?: string | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const includesValue = <Value extends string>(
  openValues: readonly Value[],
  value: Value
): boolean => openValues.includes(value);

export const toggleValue = <Value extends string>(
  openValues: readonly Value[],
  value: Value
): readonly Value[] =>
  includesValue(openValues, value)
    ? openValues.filter((openValue) => openValue !== value)
    : [...openValues, value];

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  open: boolean,
  disabled: boolean
) => [
  ...(open ? [h.DataAttribute("open", "")] : [h.DataAttribute("closed", "")]),
  ...(disabled ? [h.DataAttribute("disabled", "")] : []),
];

export const rootView = <ParentMessage>({
  children,
  openValues,
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("values", openValues.join(" ")),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(accordionRootClassName, className)),
    ],
    children
  );
};

export const itemView = <ParentMessage>({
  value,
  openValues,
  onValueChange,
  title,
  children,
  disabled = false,
  className,
  style,
  triggerClassName,
  panelClassName,
}: ItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();
  const open = includesValue(openValues, value);
  const triggerId = `${value}-trigger`;
  const panelId = `${value}-panel`;
  const state = stateAttributes(h, open, disabled);

  return h.div(
    [
      h.DataAttribute("value", value),
      ...state,
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(accordionItemClassName, className)),
    ],
    [
      h.h3(
        [h.Class(accordionHeaderClassName)],
        [
          h.button(
            [
              h.Id(triggerId),
              h.Type("button"),
              h.AriaLabel(title),
              h.Attribute("aria-expanded", open ? "true" : "false"),
              h.Attribute("aria-controls", panelId),
              ...state,
              ...(disabled ? [h.Disabled(true)] : [h.OnClick(onValueChange)]),
              h.Class(classNames(accordionTriggerClassName, triggerClassName)),
            ],
            [
              h.span([], [title]),
              h.span(
                [h.AriaHidden(true), h.Class(accordionIconClassName)],
                ["+"]
              ),
            ]
          ),
        ]
      ),
      open
        ? h.div(
            [
              h.Id(panelId),
              h.Attribute("role", "region"),
              h.Attribute("aria-labelledby", triggerId),
              ...state,
              h.Class(classNames(accordionPanelClassName, panelClassName)),
            ],
            children
          )
        : h.empty,
    ]
  );
};

export const accordionRootClassName =
  "w-full max-w-2xl divide-y divide-gray-200 rounded-lg border border-gray-200 bg-white";

export const accordionItemClassName =
  "data-[disabled]:opacity-50 data-[open]:bg-gray-50";

export const accordionHeaderClassName = "m-0";

export const accordionTriggerClassName =
  "group flex w-full cursor-pointer items-center justify-between gap-4 px-4 py-3 text-left text-sm font-medium text-gray-950 transition hover:bg-gray-50 focus-visible:outline-2 focus-visible:outline-inset focus-visible:outline-accent-600 data-[disabled]:cursor-not-allowed";

export const accordionIconClassName =
  "text-gray-500 transition-transform group-data-[open]:rotate-45";

export const accordionPanelClassName =
  "px-4 pb-4 text-sm leading-6 text-gray-600";

import { Match as M, Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, expect, test } from "vitest";

import * as Accordion from "./index";

const ToggledPanel = m("ToggledPanel", { value: S.String });
const Message = S.Union([ToggledPanel]);
type Message = typeof Message.Type;

type Model = Readonly<{
  openValues: readonly string[];
}>;

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly []] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly []]>(),
    M.tagsExhaustive({
      ToggledPanel: ({ value }) => [
        evo(model, {
          openValues: (openValues) => Accordion.toggleValue(openValues, value),
        }),
        [],
      ],
    })
  );

const view = (model: Model): Html => {
  const h = html<Message>();

  return Accordion.rootView<Message>({
    openValues: model.openValues,
    children: [
      Accordion.itemView<Message>({
        value: "base-ui",
        openValues: model.openValues,
        title: "What is Base UI?",
        onValueChange: ToggledPanel({ value: "base-ui" }),
        children: [h.p([], ["Base UI is a component library."])],
      }),
      Accordion.itemView<Message>({
        value: "getting-started",
        openValues: model.openValues,
        title: "How do I get started?",
        onValueChange: ToggledPanel({ value: "getting-started" }),
        children: [h.p([], ["Install the registry item."])],
      }),
      Accordion.itemView<Message>({
        value: "disabled",
        openValues: model.openValues,
        title: "Locked panel",
        onValueChange: ToggledPanel({ value: "disabled" }),
        disabled: true,
        children: [h.p([], ["This should not open."])],
      }),
    ],
  });
};

describe("Accordion registry view", () => {
  test("renders Base UI accordion parts and toggles multiple panels", () => {
    Scene.scene(
      { update, view },
      Scene.with({ openValues: ["base-ui"] }),
      Scene.expect(
        Scene.role("button", { name: "What is Base UI?" })
      ).toHaveAttr("aria-expanded", "true"),
      Scene.expect(Scene.text("Base UI is a component library.")).toExist(),
      Scene.expect(
        Scene.role("button", { name: "How do I get started?" })
      ).toHaveAttr("aria-expanded", "false"),
      Scene.click(Scene.role("button", { name: "How do I get started?" })),
      Scene.expect(
        Scene.role("button", { name: "How do I get started?" })
      ).toHaveAttr("aria-expanded", "true"),
      Scene.expect(Scene.text("Install the registry item.")).toExist(),
      Scene.expect(
        Scene.role("button", { name: "What is Base UI?" })
      ).toHaveAttr("aria-expanded", "true"),
      Scene.click(Scene.role("button", { name: "What is Base UI?" })),
      Scene.expect(
        Scene.role("button", { name: "What is Base UI?" })
      ).toHaveAttr("aria-expanded", "false")
    );
  });

  test("computes next open value arrays", () => {
    expect(Accordion.toggleValue(["base-ui"], "getting-started")).toEqual([
      "base-ui",
      "getting-started",
    ]);
    expect(Accordion.toggleValue(["base-ui"], "base-ui")).toEqual([]);
  });
});
